begin;
create extension if not exists pgtap with schema extensions;
set search_path=public,extensions;
select no_plan();
create function pg_temp.cid(text) returns uuid language sql immutable as $$select md5('product-report-test-'||$1)::uuid$$;
insert into auth.users(id,instance_id,aud,role,email,encrypted_password,email_confirmed_at,raw_app_meta_data,raw_user_meta_data,created_at,updated_at)
select pg_temp.cid(u),'00000000-0000-0000-0000-000000000000','authenticated','authenticated',u||'@product-report.example.test','',now(),'{}','{}',now(),now() from unnest(array['owner','outsider','cashier','technician'])u;
insert into organizations(id,name,slug,industry) select pg_temp.cid(v),v,'product-report-test-'||replace(v,'_','-'),v from unnest(array['salon','pet_care','automotive','hospitality'])v;
insert into organizations(id,name,slug,industry) values(pg_temp.cid('other'),'Other','product-report-test-other','salon');
insert into organization_memberships(id,organization_id,user_id,role) select pg_temp.cid('member-'||v),pg_temp.cid(v),pg_temp.cid('owner'),'owner' from unnest(array['salon','pet_care','automotive','hospitality'])v;
insert into organization_memberships(id,organization_id,user_id,role) values(pg_temp.cid('cashier-member'),pg_temp.cid('salon'),pg_temp.cid('cashier'),'cashier'),(pg_temp.cid('tech-member'),pg_temp.cid('salon'),pg_temp.cid('technician'),'technician'),(pg_temp.cid('other-member'),pg_temp.cid('other'),pg_temp.cid('outsider'),'owner');
insert into branches(id,organization_id,name,is_primary) select pg_temp.cid('branch-'||v),pg_temp.cid(v),'Main',true from unnest(array['salon','pet_care','automotive','hospitality','other'])v;
insert into branches(id,organization_id,name,is_primary) values(pg_temp.cid('second-branch'),pg_temp.cid('salon'),'Other',false);
insert into membership_branch_assignments(organization_id,membership_id,branch_id) values(pg_temp.cid('salon'),pg_temp.cid('cashier-member'),pg_temp.cid('branch-salon'));
insert into customers(id,organization_id,full_name) select pg_temp.cid('customer-'||v),pg_temp.cid(v),'Checkout Client' from unnest(array['salon','pet_care','automotive','hospitality','other'])v;
set local role authenticated;
select set_config('request.jwt.claims',jsonb_build_object('sub',pg_temp.cid('owner'),'role','authenticated')::text,true);
select is(get_checkout_product_report(pg_temp.cid('branch-salon'),1),'{"sales":0,"paid":0,"balance":0,"rows":[]}'::jsonb,'empty branch has a valid report');
select throws_ok($$select get_checkout_product_report(pg_temp.cid('branch-other'),1)$$,'42501','Report access required','foreign tenant denied');
select throws_ok($$select get_checkout_product_report(null,1)$$,'42501','Report access required','missing branch denied');
select throws_ok($$select get_checkout_product_report(pg_temp.cid('branch-salon'),0)$$,'22023','Invalid page','zero page rejected');
select throws_ok($$select get_checkout_product_report(pg_temp.cid('branch-salon'),null)$$,'22023','Invalid page','null page rejected');
select throws_ok($$select get_checkout_product_report(pg_temp.cid('branch-salon'),10001)$$,'22023','Invalid page','page bound enforced');
select set_config('request.jwt.claims',jsonb_build_object('sub',pg_temp.cid('cashier'),'role','authenticated')::text,true);
select lives_ok($$select get_checkout_product_report(pg_temp.cid('branch-salon'),1)$$,'assigned cashier can read product report');
select throws_ok($$select get_checkout_product_report(pg_temp.cid('second-branch'),1)$$,'42501','Report access required','unassigned branch denied');
select set_config('request.jwt.claims',jsonb_build_object('sub',pg_temp.cid('technician'),'role','authenticated')::text,true);
select throws_ok($$select get_checkout_product_report(pg_temp.cid('branch-salon'),1)$$,'42501','Report access required','technician cannot read financial product report');
set local role anon;
select throws_ok($$select get_checkout_product_report(pg_temp.cid('branch-salon'),1)$$,'42501',null,'anonymous access denied');
select * from finish();
rollback;
